package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class GradeSevenDecimalProductScopeTest {
 private static final String SYSTEM="na-nied-primary-2024-v1";
 private static Question q(String prompt){return new Question("decimalMul",prompt,"private expression","999");}
 @Test public void NormalNaSevenSameTopicSuppliesWholeAndDecimalRightShapesAsTypedAnswers(){
  var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals(SYSTEM)).findFirst().orElseThrow();assertTrue(pack.inGrade("decimalMul",7));assertEquals(1,Catalog.ALL.stream().filter(s->s.id.equals("decimalMul")).count());CurriculumLimits limits=GlobalCurriculum.limits(SYSTEM,"decimalMul",7);assertTrue(limits.includeWholeDecimalProducts());assertTrue(limits.decimalDirectAnswers());assertEquals(2,limits.decimalPlaces(1));assertEquals(3,limits.answerDecimalPlaces(1));assertEquals(3,limits.wholeProductDecimalPlaces());assertEquals(99,limits.wholeProductMaximum());assertEquals(99,limits.wholeMultiplierMaximum());
  for(boolean mc:List.of(false,true)){Generator generator=new Generator(new Random(365));List<String> recent=new ArrayList<>();int wholeCount=0,decimalCount=0;Set<Integer> wholePlaces=new HashSet<>();boolean twoDigit=false;
   for(int i=0;i<300;i++){Question q=generator.next("decimalMul",recent,mc,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var original=DecimalWholeProducts.readGeneral(q);assertNotNull(original);assertTrue(limits.allows(q));assertEquals("number",q.kind);assertTrue(q.choices.isEmpty());assertEquals(-1,q.correctChoice);assertTrue(new Checker().check(q,List.of(),List.of(original.value().toPlainString())).correct());HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());if(original.wholeRight()){wholeCount++;assertEquals(6,h.size());assertTrue(original.left().compareTo(new BigDecimal("100"))<0);assertTrue(original.right().compareTo(new BigDecimal("99"))<=0);assertTrue(original.left().scale()<=3);wholePlaces.add(original.left().scale());twoDigit|=original.right().compareTo(BigDecimal.TEN)>=0;}else{decimalCount++;assertEquals(9,h.size());assertTrue(original.left().scale()<=2);assertTrue(original.right().scale()<=2);assertTrue(original.value().stripTrailingZeros().scale()<=3);}}
   assertTrue(wholeCount>0);assertTrue(decimalCount>0);assertTrue(wholePlaces.contains(3));assertTrue(twoDigit);
  }Question ordinary=new Generator(new Random(3651)).create(Catalog.get("decimalMul"));assertNotNull(DecimalWholeProducts.readGeneral(ordinary));assertNotNull(HelpPlan.forQuestion(ordinary));
 }
 @Test public void WholeSelectionAndExistingDecimalSelectionUseSeparateDeclaredPublicControls(){
  CurriculumLimits limits=GlobalCurriculum.limits(SYSTEM,"decimalMul",7);for(String prompt:List.of("99.999 × 99","0.000 × 99","3.375 × 13","4.15 × 0.2","1.25 × 2.0")){Question q=q(prompt);q.expression=null;q.answers=null;assertTrue(prompt,limits.allows(q));assertNotNull(HelpPlan.forQuestion(q));assertNull(q.expression);assertNull(q.answers);}for(String prompt:List.of("1.2345 × 24","100.00 × 24","3.75 × 100","3.375 × 13.0","1.23 × 0.12")){assertFalse(prompt,limits.allows(q(prompt)));assertTrue(prompt,CurriculumLimits.NONE.allows(q(prompt)));}
  assertTrue(new CurriculumLimits("decimalPlaces=4").allows(q("1.2345 × 2.0")));assertFalse(new CurriculumLimits("decimalPlaces=3").allows(q("1.2345 × 2.0")));assertTrue(new CurriculumLimits("integerSecondOperand=true").allows(q("1.5 × 2.0")));assertFalse(new CurriculumLimits("integerSecondOperand=true").allows(q("1.5 × 2.1")));assertTrue(new CurriculumLimits("maxResult=0.3;answerDecimalPlaces=1;minGiven=0.2;maxGiven=1.5").allows(q("0.2 × 1.5")));assertFalse(new CurriculumLimits("maxResult=0.299").allows(q("0.2 × 1.5")));assertFalse(new CurriculumLimits("answerDomain=integer").allows(q("0.2 × 1.5")));assertTrue(new CurriculumLimits("wholeDigits=2;secondDigits=1;secondDecimalPlaces=1").allows(q("12.3 × 2.0")));assertFalse(new CurriculumLimits("maxSecondOperand=1").allows(q("0.2 × 2")));assertFalse(new CurriculumLimits("denominators=2").allows(q("0.2 × 2")));assertFalse(new CurriculumLimits("wholeProductMaximum=99").allows(q("0.2 × 2")));for(String invalid:List.of("wholeProductDecimalPlaces=4","wholeProductMaximum=100","wholeMultiplierMaximum=100","includeWholeDecimalProducts=unknown")){try{new CurriculumLimits(invalid);fail(invalid);}catch(IllegalArgumentException expected){}}
 }
 @Test public void NaSixAndEnglishLegacySupplySignaturesScopesAndChoicesRemainAccessible(){
  CurriculumLimits six=GlobalCurriculum.limits(SYSTEM,"decimalMul",6),english=GlobalCurriculum.limits("england-primary-2021-v1","decimalMul",6);assertFalse(six.includeWholeDecimalProducts());assertFalse(english.includeWholeDecimalProducts());assertTrue(DecimalWholeProducts.supports("decimalMul",six));assertTrue(DecimalWholeProducts.supports("decimalMul",english));assertFalse(DecimalWholeProducts.supports("decimalMul",CurriculumLimits.NONE));Random directRandom=new Random(3652);Generator normal=new Generator(new Random(3652));for(int i=0;i<60;i++){Question direct=DecimalWholeProducts.next(directRandom,six,Map.of()),actual=normal.next("decimalMul",List.of(),false,six);assertEquals(direct.signature(),actual.signature());assertEquals(6,HelpPlan.forQuestion(actual).size());}
  Generator yearSix=new Generator(new Random(3653));for(int i=0;i<60;i++){var v=DecimalWholeProducts.read(yearSix.next("decimalMul",List.of(),false,english));assertNotNull(v);assertEquals(2,new BigDecimal(v.raw()).scale());assertTrue(new BigDecimal(v.raw()).compareTo(BigDecimal.TEN)<0);}Question legacyChoices=new Generator(new Random(3654)).next("decimalMul",List.of(),true,six);assertFalse(legacyChoices.choices.isEmpty());assertTrue(legacyChoices.correctChoice>=0);assertTrue(new Checker().check(legacyChoices,List.of(),List.of(legacyChoices.choices.get(legacyChoices.correctChoice))).correct());assertEquals("9.99 × 99",DecimalWholeProducts.make(999,99).prompt);assertEquals("989.01",DecimalWholeProducts.make(999,99).answers[0]);assertEquals("0",DecimalWholeProducts.make(0,99).answers[0]);
 }
 @Test public void DecimalRightB9FourPlaceCountriesAndDivisionContractsAreNotReplacedByWholeProducts(){
  CurriculumLimits seven=GlobalCurriculum.limits(SYSTEM,"decimalMul",7);assertTrue(seven.allows(q("4.15 × 0.2")));assertEquals(9,HelpPlan.forQuestion(q("4.15 × 0.2")).size());assertTrue(new Checker().check(q("4.15 × 0.2"),List.of(),List.of("0.83")).correct());assertFalse(seven.allows(q("1.23 × 0.12")));assertTrue(GlobalCurriculum.limits("ke-kicd-cbc-2024-v1","decimalMul",7).allows(q("1.2345 × 0.2")));assertEquals("decimal-arithmetic-relations-v1",DecimalWholeProducts.guide(q("1.2345 × 0.2")).teachingVersion);
  Question quotient=DecimalWholeQuotients.make("3.375",13);StudyGuide stored=quotient.studyGuide;assertEquals("decimal-whole-quotient-v1",stored.teachingVersion);HelpPlan divisionHelp=HelpPlan.forQuestion(quotient);assertEquals(9,divisionHelp.size());assertEquals(stored.teachingVersion,quotient.studyGuide.teachingVersion);assertEquals(stored.frames.size(),quotient.studyGuide.frames.size());for(int stage=0;stage<stored.frames.size();stage++){StudyGuide.Frame prior=stored.frames.get(stage),after=quotient.studyGuide.frames.get(stage);assertEquals(prior.instruction,after.instruction);assertEquals(prior.before,after.before);assertEquals(prior.after,after.after);assertEquals(prior.expected,after.expected);assertEquals(prior.inputFormat,after.inputFormat);assertTrue(divisionHelp.step(stage).accepts(prior.expected));}assertTrue(new Checker().check(quotient,List.of(),List.of("27/104")).correct());assertFalse(HelpPlan.forQuestion(quotient).canTransfer());Question add=new Question("decimalAdd","1.2 + 0.03","poison","999");assertTrue(new Checker().check(add,List.of(),List.of("1.23")).correct());assertEquals(8,HelpPlan.forQuestion(add).size());
 }
}
